    """Propagate marker colors onto repeated solid 2x2 patches in their bands."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] not in (0, 1)]
    # A marker labels the repeated 2x2 solid motif nearest it; assigning each
    # qualifying patch by its closest marker keeps separate color families apart.
    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[i][j] == 1 for i in (r, r + 1) for j in (c, c + 1)):
                mr, mc, color = min(markers, key=lambda m: (m[0] - r) ** 2 + (m[1] - c) ** 2)
                # Keep propagation local to the marker's associated motif family.
                if abs(mr - r) + abs(mc - c) <= 9:
                    for i in (r, r + 1):
                        for j in (c, c + 1):
                            out[i][j] = color
    return out

if __name__ == '__main__':
    import json, sys
    grid = json.load(sys.stdin)
    result = transform(grid)
    assert result and all(len(row) == len(result[0]) for row in result)
    assert all(0 <= v <= 9 for row in result for v in row)
    print(json.dumps(result))
