 "content": "def transform(grid):
    """Transfer the 2x2 solid motif across all 1-components, colored by markers.

    Each rare-color marker belongs to a same-color 1-component, and its color
    replaces every full 2x2 block of 1s in that component. Components without
    a seed remain unchanged.
    """
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for sr in range(h):
        for sc in range(w):
            if grid[sr][sc] not in (1,) and grid[sr][sc] not in range(2, 10):
                continue
            if (sr, sc) in seen:
                continue
            # 4-connected components of foreground cells (1 plus rare marker).
            stack = [(sr, sc)]
            comp = []
            colors = set()
            seen.add((sr, sc))
            while stack:
                r, c = stack.pop()
                comp.append((r, c))
                if grid[r][c] != 1:
                    colors.add(grid[r][c])
                for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] in (1,) + tuple(range(2,10)) and (nr,nc) not in seen:
                        seen.add((nr,nc))
                        stack.append((nr,nc))
            if not colors:
                continue
            color = min(colors)
            cells = set(comp)
            for r, c in comp:
                if grid[r][c] != 1:
                    continue
                if all((rr, cc) in cells for rr in (r, r+1) for cc in (c, c+1)):
                    for rr in (r, r+1):
                        for cc in (c, c+1):
                            if grid[rr][cc] == 1:
                                out[rr][cc] = color
    return out

if __name__ == '__main__':
    import json, sys
    grid = json.load(sys.stdin)
    result = transform(grid)
    assert len(result) == len(grid) and all(len(row) == len(grid[0]) for row in result)
    assert all(isinstance(x, int) and 0 <= x <= 9 for row in result for x in row)
    print(json.dumps(result))
",
 "cross_profile": false
}

